// Referencia APA 7 (texto plano y HTML con título en cursiva)
window.apa = function (d, html = true) {
  const a = d.apa, t = html ? `<i>${a.titulo}</i>` : a.titulo;
  const partes = a.autor ? [`${a.autor} (${a.fecha}).`, `${t}${a.nota ? ` (${a.nota})` : ''}.`] : [`${t}${a.nota ? ` (${a.nota})` : ''}.`, `(${a.fecha}).`];
  if (a.sitio) partes.push(`${a.sitio}.`);
  partes.push(d.url);
  return partes.join(' ');
};
